# osprey: flavor=python
@effect
class Files:
    def write(path: str, text: str) -> Result[int, Error]: ...

@effect
class Log:
    def info(text: str) -> None: ...

# Deep in the app: no disk or logger is passed in.
def write_lock(lock):
    match perform(Files.write("osprey.lock", lock)):
        case Success():
            return "installed"
        case Error(message=message):
            return f"rolled back: {message}"

def install(name):
    perform(Log.info(f"resolving {name}"))
    return write_lock(f"{name} = 2")

@handler(Files)
class disk:
    def write(path, text):
        return writeFile(path, text)

@handler(Log)
class terminal:
    def info(text):
        print(f"log: {text}")

@handler(Files)
class full_disk:
    def write(_path, _text):
        return Error(message="disk full")

@handler(Log)
class expect_resolving:
    def info(text):
        expect(text, "resolving serde")

# The app's edge picks the real disk and logger, once.
with disk:
    with terminal:
        print(install("serde"))

# A test swaps in a full disk. The app code does not change.
def full_disk_test():
    with full_disk:
        with expect_resolving:
            return expect(install("serde"), "rolled back: disk full")

test("a full disk rolls back", full_disk_test)
